sys_ui_action.client_script_v2:
function onClick() {

    var TradeSysId = g_form.getValue("trade_id");
    console.log('TradeSysId ' + TradeSysId);
    var TaskSysId = g_form.getUniqueValue();
    var PosattributeSync = g_form.getValue("position_attribute_sync");

    if (PosattributeSync == 'Attribute Sync is in progress') {
        g_form.addInfoMessage('Position Attribute Sync is already in progress');
        //action.setRedirectURL(current);
        //location.reload();
    } else {
        if (g_form.getValue("trade_id.securities_account") == '' || g_form.getValue("trade_id.security_id") == '') {
            g_form.addErrorMessage('Holdings data sync was not completed due to missing security information.');
            //action.setRedirectURL(current);
            //location.reload();
        } else {

            var gajax = new GlideAjax("x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils");
            gajax.addParam("sysparm_name", "refreshPositionDataAPICall");
            gajax.addParam("sysparm_id", TradeSysId);
            gajax.addParam("sysparm_attribute_sync", positionattributeSync);

            gajax.getXMLAnswer(openList);
            //location.reload();

        }

    }

}

function openList(url) {
    if (url == "Attribute Sync is in progress") {
        g_form.addInfoMessage("Attribute Sync is already in progress");
    } else if (url == "security account or security id is empty") {
        g_form.addErrorMessage("Holdings data sync was not completed due to missing security information.");
    }
}
